def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    op_def = 0
    my_def = 0
    for x in opp:
        if x == 'D':
            op_def += 1
    for x in my:
        if x == 'D':
            my_def += 1
    op_c = n - op_def

    last_opp = opp[-1]
    last_my = my[-1]
    op_d_streak = streak(opp, 'D')
    my_d_streak = streak(my, 'D')

    # Early game: mostly cooperate, probe lightly.
    if n < 4:
        if n == 3 and last_opp == 'D':
            return 'D'
        return 'C'

    # Endgame: defect in final rounds, cooperate at 90 for possible last mutual.
    remaining = 100 - n
    if remaining <= 2:
        return 'D'
    if n == 90:
        return 'C'

    # Strong response to repeated defection.
    if op_d_streak >= 3:
        return 'D'
    if op_d_streak == 2:
        if my_d_streak >= 1:
            return 'C'
        return 'D'

    if last_opp == 'D':
        # Single recent defection: retaliate, but if we just did, forgive.
        if last_my == 'D':
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if n >= 8:
        recent_len = 10 if n >= 10 else n
        recent_opp_def = 0
        for i in range(n - recent_len, n):
            if opp[i] == 'D':
                recent_opp_def += 1
        op_rate = op_def / float(n)

        # Heavy defector even if recently quiet: defect.
        if op_rate >= 0.6:
            return 'D'
        if op_rate >= 0.4 and recent_opp_def >= 3:
            return 'D'

        # Mostly cooperative: mostly cooperate with rare exploitation.
        if op_rate <= 0.15:
            if n > 20 and n % 23 == 0 and last_my == 'C':
                return 'D'
            return 'C'

        # Moderate: be cautious, occasionally defect to test.
        if n % 19 == 0 and last_my == 'C':
            return 'D'
        return 'C'

    return 'C'
